        GrammarBook.g("pras-b1", "Czas teraźniejszy Präsens", "B1", "Zdanie z schon i noch", "Czas teraźniejszy z schon, noch, erst opisuje stan teraz, nie przyszłość z kalendarza.", "Ich arbeite noch. Der Kollege ist schon weg.", [GrammarBook.gl("Ich bin noch auf der Baustelle.", "Jeszcze jestem na budowie."), GrammarBook.gl("Der Beton ist schon da.", "Beton już jest.")], [GrammarBook.gl("Wir warten erst auf die Lieferung.", "Najpierw czekamy na dostawę.")], "Co znaczy noch?", ["jeszcze", "już", "nigdy"], 0, ["Ich", "bin", "noch", "auf", "der", "Baustelle"], "schon", "Der Kollege ist ___ weg.", ["schon", "noch", "erst"], 0, "Jeszcze pracuję.", "Ich arbeite noch.", ["arbeite", "noch"]),
