        GrammarBook.g("perf-b2", "Czas przeszły Perfekt", "B2", "Kolejność w dłuższej przeszłości", "Najpierw habe albo bin, na końcu imiesłów. Reszta siada pośrodku, także weil osobno.", "Ich bin zu spät gekommen, weil der Bus Verspätung hatte.", [GrammarBook.gl("Ich habe den Fehler erst spät gesehen.", "Błąd zobaczyłem dopiero późno."), GrammarBook.gl("Sie ist schon gegangen.", "Ona już poszła.")], [GrammarBook.gl("Wir haben die Plane festgebunden, bevor es regnete.", "Związaliśmy plandekę, zanim zaczęło padać.")], "Które bin pasuje?", ["Ich bin gekommen.", "Ich habe gekommen.", "Ich bin gesagt."], 0, ["Ich", "bin", "zu", "spät", "gekommen"], "hatte", "Sie ist schon ___.", ["gegangen", "gehen", "geht"], 0, "Przyszedłem za późno.", "Ich bin zu spät gekommen.", ["bin", "gekommen"]),
        GrammarBook.g("prat-a1", "Czas przeszły Präteritum", "A1", "War i hatte na start", "Na początku wystarczą ci dwie formy, które słyszysz codziennie: war i hatte.", "Ich war krank. Ich hatte keine Zeit.", [GrammarBook.gl("Ich war zu Hause.", "Byłem w domu."), GrammarBook.gl("Ich hatte den Schlüssel.", "Miałem klucz.")], [GrammarBook.gl("Der Chef war nicht da.", "Szefa nie było.")], "Jak powiesz byłem?", ["Ich war", "Ich bin war", "Ich hatte bin"], 0, ["Ich", "war", "zu", "Hause"], "hatte", "Ich ___ den Schlüssel.", ["hatte", "war", "habe gehabt tylko tak"], 0, "Byłem w domu.", "Ich war zu Hause.", ["war"]),
        GrammarBook.g("prat-b1", "Czas przeszły Präteritum", "B1", "Kam, ging, sagte", "W opowieści o wczoraj szef często rzuca krótkie Präteritum: kam, ging, sagte. W odpowiedzi możesz zostać przy Perfekt.", "Der Chef kam um sieben und sagte Bescheid.", [GrammarBook.gl("Er ging früher.", "Wyszedł wcześniej."), GrammarBook.gl("Sie sagte nichts.", "Nic nie powiedziała.")], [GrammarBook.gl("Der Beton kam zu spät.", "Beton przyjechał za późno.")], "Co znaczy kam?", ["przyjechał, przyszedł", "przyjedzie", "został"], 0, ["Der", "Beton", "kam", "zu", "spät"], "gesagt", "Der Chef ___ um sieben.", ["kam", "kommt", "gekommen"], 0, "Beton przyjechał za późno.", "Der Beton kam zu spät.", ["kam"]),
        GrammarBook.g("prat-b2", "Czas przeszły Präteritum", "B2", "Kiedy Perfekt, kiedy Präteritum", "O swoim dniu mówisz habe gemacht. War, hatte i kam wplatasz, bo tak brzmią z ust Niemców. Nie przerabiasz całego dnia na kam.", "Ich war müde, aber ich habe weitergearbeitet.", [GrammarBook.gl("Ich hatte kein Werkzeug, also habe ich Tim gefragt.", "Nie miałem narzędzia, więc zapytałem Tima."), GrammarBook.gl("Es war laut, trotzdem habe ich ihn verstanden.", "Było głośno, a i tak go zrozumiałem.")], [GrammarBook.gl("Der Kran ging nicht, wir haben von Hand getragen.", "Żuraw nie działał, nosiliśmy ręcznie.")], "Co jest naturalne o tobie?", ["Ich habe gearbeitet.", "Ich arbeitete den ganzen Tag w zwykłej rozmowie", "Ich bin gearbeitet."], 0, ["Ich", "war", "müde"], "habe", "Ich ___ kein Werkzeug.", ["hatte", "habe gehabt zawsze", "war"], 0, "Byłem zmęczony, ale pracowałem dalej.", "Ich war müde, aber ich habe weitergearbeitet.", ["war", "habe"]),
