        GrammarBook.g("art-b1", "Rodzajniki der, die, das", "B1", "Rodzajnik po przymiotniku nie zgadujesz", "Przymiotnik nie zmienia rodzaju. Die nasse Wand zostaje die, nie das.", "die nasse Wand, der neue Helm", [GrammarBook.gl("der lange Tag", "długi dzień"), GrammarBook.gl("das schwere Teil", "ciężki element")], [GrammarBook.gl("die linke Seite", "lewa strona")], "Jaki rodzajnik przy Wand?", ["die", "das", "der"], 0, ["die", "nasse", "Wand"], "der", "___ linke Seite ist länger.", ["Die", "Der", "Das"], 0, "Lewa strona jest dłuższa.", "Die linke Seite ist länger.", ["die", "seite"]),
