        GrammarBook.g("przy-a2", "Przyimki i ich przypadki", "A2", "Aus, von, nach", "Aus to ze środka. Von to od osoby albo od miejsca. Nach to kierunek do miast i do domu.", "Ich komme aus Polen. Ich fahre nach Hause.", [GrammarBook.gl("Das Teil ist aus dem Container.", "Część jest z kontenera."), GrammarBook.gl("Die Mail ist von der Firma.", "Mail jest od firmy.")], [GrammarBook.gl("Nach der Schicht fahre ich nach Hause.", "Po zmianie jadę do domu.")], "Jak powiesz do domu?", ["nach Hause", "zu Hause jako kierunek", "nach der Hause"], 0, ["Ich", "fahre", "nach", "Hause"], "aus", "Die Mail ist ___ der Firma.", ["von", "nach", "aus"], 0, "Jadę do domu.", "Ich fahre nach Hause.", ["nach", "hause"]),
