        GrammarBook.g("przy-b2", "Przyimki i ich przypadki", "B2", "Wegen i trotz w mowie i w piśmie", "W piśmie do urzędu: wegen des Regens. Na budowie usłyszysz wegen dem Regen. Znasz obie, w mailu bierzesz staranniejszą.", "Wegen des Regens stoppen wir.", [GrammarBook.gl("Trotz des Lärms habe ich ihn verstanden.", "Mimo hałasu go zrozumiałem."), GrammarBook.gl("Wegen der Lieferung warten wir.", "Czekamy przez dostawę.")], [GrammarBook.gl("Wegen des Windes bleiben wir unten.", "Przez wiatr zostajemy na dole.")], "Co dasz w mailu do urzędu?", ["wegen des Regens", "wegen dem Regen", "wegen den Regen"], 0, ["Wegen", "des", "Windes", "bleiben", "wir", "unten"], "dem", "Wir warten wegen ___ Lieferung.", ["der", "des", "den"], 0, "Przez wiatr zostajemy na dole.", "Wegen des Windes bleiben wir unten.", ["wegen"]),
        GrammarBook.g("wechs-a1", "Wechselpräpositionen", "A1", "Dokąd czy gdzie, na start", "Na początek dwa obrazki. Dokąd: in den Container. Gdzie jesteś: im Container.", "Ich gehe in den Container. Ich bin im Container.", [GrammarBook.gl("Leg das auf den Tisch.", "Połóż to na stół."), GrammarBook.gl("Es liegt auf dem Tisch.", "To leży na stole.")], [GrammarBook.gl("Komm auf die Baustelle.", "Chodź na budowę.")], "Które znaczy gdzie jesteś?", ["im Container", "in den Container", "auf den Tisch"], 0, ["Ich", "bin", "im", "Container"], "den", "Es liegt auf ___ Tisch.", ["dem", "den", "das"], 0, "Jestem w kontenerze.", "Ich bin im Container.", ["im"]),
        GrammarBook.g("wechs-b1", "Wechselpräpositionen", "B1", "An i neben", "An die Wand to ruch do ściany. An der Wand to już wisi. Neben działa tak samo.", "Häng die Plane an die Wand. Sie hängt an der Wand.", [GrammarBook.gl("Stell die Leiter neben die Tür.", "Postaw drabinę obok drzwi."), GrammarBook.gl("Die Leiter steht neben der Tür.", "Drabina stoi obok drzwi.")], [GrammarBook.gl("Wir fahren an die Rampe.", "Podjeżdżamy do rampy.")], "Które jest ruchem?", ["an die Wand", "an der Wand", "neben der Tür"], 0, ["Stell", "die", "Leiter", "neben", "die", "Tür"], "der", "Die Plane hängt an ___ Wand.", ["der", "die", "das"], 0, "Postaw drabinę obok drzwi.", "Stell die Leiter neben die Tür.", ["neben", "die"]),
