        GrammarBook.g("trenn-a2", "Czasowniki rozdzielnie złożone", "A2", "Mitnehmen i anrufen", "Przedrostek idzie na koniec zdania głównego. W bezokoliczniku po muss wraca do czasownika.", "Ich nehme den Helm mit. Ich muss anrufen.", [GrammarBook.gl("Ruf mich um sechs an.", "Zadzwoń do mnie o szóstej."), GrammarBook.gl("Nimmst du die Säge mit?", "Bierzesz piłę ze sobą?")], [GrammarBook.gl("Fang links an.", "Zacznij od lewej.")], "Gdzie jest mit?", ["Na końcu", "Przy nehme", "Przed den"], 0, ["Ich", "nehme", "den", "Helm", "mit"], "an", "Ruf mich um sechs ___.", ["an", "anruf", "zu"], 0, "Biorę kask ze sobą.", "Ich nehme den Helm mit.", ["nehme", "mit"]),
        GrammarBook.g("trenn-b1", "Czasowniki rozdzielnie złożone", "B1", "W Perfekt wraca razem", "W czasie przeszłym przedrostek zostaje przy ge-: angerufen, mitgenommen, angefangen.", "Ich habe dich angerufen.", [GrammarBook.gl("Hast du die Säge mitgenommen?", "Wziąłeś piłę?"), GrammarBook.gl("Wir haben hinten angefangen.", "Zaczęliśmy z tyłu.")], [GrammarBook.gl("Ich habe den Chef nicht erreicht.", "Nie złapałem szefa.")], "Jak brzmi przeszłość od anrufen?", ["angerufen", "gerufen an", "geanrufen"], 0, ["Ich", "habe", "dich", "angerufen"], "mit", "Wir haben hinten ___.", ["angefangen", "fangen an", "gefangen an"], 0, "Zadzwoniłem do ciebie.", "Ich habe dich angerufen.", ["habe", "angerufen"]),
        GrammarBook.g("trenn-b2", "Czasowniki rozdzielnie złożone", "B2", "Przedrostek w zdaniu z weil", "Po weil cały czasownik, już z przedrostkiem, idzie na koniec. Nie zostawiasz an osobno w środku.", "Ich komme später, weil ich den Chef anrufe.", [GrammarBook.gl("Ich bleibe, weil ich noch aufräume.", "Zostaję, bo jeszcze sprzątam."), GrammarBook.gl("Sag Bescheid, wenn du anfängst.", "Daj znać, jak zaczniesz.")], [GrammarBook.gl("Wir warten, weil die Lieferung ausfällt.", "Czekamy, bo dostawa wypada.")], "Co jest dobre?", ["weil ich den Chef anrufe", "weil ich anrufe den Chef", "weil ich rufe den Chef an"], 0, ["weil", "ich", "noch", "aufräume"], "an", "Sag Bescheid, wenn du ___.", ["anfängst", "fängst an", "an fängst"], 0, "Przyjdę później, bo dzwonię do szefa.", "Ich komme später, weil ich den Chef anrufe.", ["weil", "anrufe"]),
        GrammarBook.g("zwr-a1", "Czasowniki zwrotne", "A1", "Mich przy sobie", "Kilka codziennych czasowników bierze mich: duschen, setzen, treffen w liczbie mnogiej uns.", "Ich dusche mich. Wir treffen uns.", [GrammarBook.gl("Ich setze mich.", "Siadam."), GrammarBook.gl("Wir treffen uns um sieben.", "Spotykamy się o siódmej.")], [GrammarBook.gl("Zieh dich um, der Pulli ist nass.", "Przebierz się, bluza jest mokra.")], "Co pasuje?", ["Ich dusche mich.", "Ich dusche mir.", "Ich mich dusche."], 0, ["Wir", "treffen", "uns", "um", "sieben"], "mich", "Ich setze ___.", ["mich", "mir", "sich"], 0, "Spotykamy się o siódmej.", "Wir treffen uns um sieben.", ["treffen", "uns"]),
        GrammarBook.g("zwr-b1", "Czasowniki zwrotne", "B1", "Mich czy mir", "Mich jest biernikiem, mir celownikiem. Przy części ciała często mir: ich wasche mir die Hände.", "Ich wasche mir die Hände. Ich ziehe mich um.", [GrammarBook.gl("Ich kaufe mir einen Kaffee.", "Kupuję sobie kawę."), GrammarBook.gl("Er rasiert sich.", "Goli się.")], [GrammarBook.gl("Ich merke mir die Hausnummer.", "Zapamiętuję numer domu.")], "Co przy die Hände?", ["mir", "mich", "mein"], 0, ["Ich", "wasche", "mir", "die", "Hände"], "mich", "Ich ziehe ___ um.", ["mich", "mir", "mein"], 0, "Myję ręce.", "Ich wasche mir die Hände.", ["mir", "hände"]),
        GrammarBook.g("zwr-b2", "Czasowniki zwrotne", "B2", "Czasownik, który tylko wygląda na zwrotny", "Nie każdy sich jest zwrotny w polskim sensie. Sich etwas merken to zapamiętać. Sich beeilen to spieszyć się.", "Ich beeile mich. Ich merke mir den Termin.", [GrammarBook.gl("Beeil dich, der Bus kommt.", "Spiesz się, autobus jedzie."), GrammarBook.gl("Merk dir die Rampe, nicht die alte.", "Zapamiętaj rampę, nie starą.")], [GrammarBook.gl("Wir müssen uns entscheiden.", "Musimy się zdecydować.")], "Co znaczy beeil dich?", ["Spiesz się", "Uspokój się", "Usiądź"], 0, ["Beeil", "dich", "der", "Bus", "kommt"], "mir", "Merk ___ den Termin.", ["dir", "dich", "dein"], 0, "Spieszę się.", "Ich beeile mich.", ["beeile", "mich"]),
        GrammarBook.g("odm-a2", "Odmiana czasowników", "A2", "Ihr i sie", "Ihr przy ekipie, do kilku kolegów: ihr holt. Sie przy obcym i przy oni: sie holen albo holen Sie.", "Ihr holt die Leiter. Holen Sie die Leiter.", [GrammarBook.gl("Was macht ihr?", "Co robicie?"), GrammarBook.gl("Was machen Sie?", "Co pan robi?")], [GrammarBook.gl("Ihr fangt links an.", "Zaczynacie od lewej.")], "Jak powiesz do dwóch kolegów?", ["ihr holt", "Sie holt", "du holt"], 0, ["Ihr", "holt", "die", "Leiter"], "holen", "Was ___ ihr?", ["macht", "machen", "macht Sie"], 0, "Przynosicie drabinę.", "Ihr holt die Leiter.", ["holt"]),
        GrammarBook.g("odm-b1", "Odmiana czasowników", "B1", "Mocne czasowniki w całym wzorze", "Sprechen: ich spreche, du sprichst, er spricht, ihr sprecht. Zmiana jest tylko w du i er.", "Du sprichst. Er spricht. Ihr sprecht.", [GrammarBook.gl("Du gibst mir den Bohrer.", "Dajesz mi wiertło."), GrammarBook.gl("Er gibt ihn weiter.", "On podaje go dalej.")], [GrammarBook.gl("Du siehst die Kante nicht.", "Nie widzisz krawędzi.")], "Co pasuje do ihr?", ["sprecht", "spricht", "sprichst"], 0, ["Du", "gibst", "mir", "den", "Bohrer"], "gibt", "Er ___ ihn weiter.", ["gibt", "gibst", "geben"], 0, "Dajesz mi wiertło.", "Du gibst mir den Bohrer.", ["gibst"]),
        GrammarBook.g("odm-b2", "Odmiana czasowników", "B2", "Forma grzeczna nie jest liczbą mnogą w głowie", "Holen Sie wygląda jak oni, ale mówisz do jednej osoby. Czasownik jest jak przy sie, a słowo Sie piszesz wielką literą.", "Können Sie das wiederholen?", [GrammarBook.gl("Haben Sie den Ausweis dabei?", "Ma pan dowód?"), GrammarBook.gl("Kommen Sie bitte mit.", "Proszę iść ze mną.")], [GrammarBook.gl("Wissen Sie, wo die Akte liegt?", "Czy wie pan, gdzie leżą akta?")], "Do kogo jest Können Sie?", ["Do jednej osoby grzecznie", "Tylko do grupy", "Do dziecka"], 0, ["Können", "Sie", "das", "wiederholen"], "du", "___ Sie den Ausweis dabei?", ["Haben", "Hast", "Hat"], 0, "Ma pan dowód przy sobie?", "Haben Sie den Ausweis dabei?", ["haben", "sie"]),
        GrammarBook.g("nicht-a2", "Przeczenia nicht i kein", "A2", "Kein odmienia się jak rodzajnik", "Kein, keine, keinen, keinem. Wybierasz tak samo jak ein, tylko zaprzeczasz.", "Ich habe keinen Helm und keine Zeit.", [GrammarBook.gl("Wir haben kein Material.", "Nie mamy materiału."), GrammarBook.gl("Sie hat keine Pause gemacht.", "Nie zrobiła przerwy.")], [GrammarBook.gl("Ich sehe keinen Fehler.", "Nie widzę błędu.")], "Co przed der Helm w bierniku?", ["keinen", "kein", "keine"], 0, ["Ich", "habe", "keinen", "Helm"], "nicht", "Wir haben ___ Material.", ["kein", "keinen", "nicht"], 0, "Nie mam czasu.", "Ich habe keine Zeit.", ["keine"]),
        GrammarBook.g("nicht-b1", "Przeczenia nicht i kein", "B1", "Nicht na właściwym miejscu", "Nicht stoi zwykle przed tym, co negujesz. Przed czasownikiem na końcu, gdy negujesz całą czynność.", "Ich habe nicht den roten, sondern den blauen genommen.", [GrammarBook.gl("Ich komme nicht um sechs, sondern um sieben.", "Przyjdę nie o szóstej, tylko o siódmej."), GrammarBook.gl("Das ist nicht mein Schlüssel.", "To nie jest mój klucz.")], [GrammarBook.gl("Wir arbeiten heute nicht draußen.", "Dziś nie pracujemy na zewnątrz.")], "Co negujesz w pierwszym zdaniu?", ["Czerwoną rzecz, nie całą czynność", "Że w ogóle coś wziąłeś", "Osobę"], 0, ["Ich", "komme", "nicht", "um", "sechs"], "kein", "Das ist ___ mein Schlüssel.", ["nicht", "kein", "keine"], 0, "Przyjdę o siódmej, nie o szóstej.", "Ich komme nicht um sechs, sondern um sieben.", ["nicht", "sondern"]),
        GrammarBook.g("nicht-b2", "Przeczenia nicht i kein", "B2", "Nicht nur", "Nicht nur ..., sondern auch ... dodaje, a nie kasuje. Przydaje się przy stawce i zakresie roboty.", "Ich mache nicht nur die Fugen, sondern auch die Abnahme.", [GrammarBook.gl("Das gilt nicht nur heute.", "To nie obowiązuje tylko dziś."), GrammarBook.gl("Er ist nicht nur Kollege, sondern auch Vorarbeiter.", "Jest nie tylko kolegą, ale i brygadzistą.")], [GrammarBook.gl("Wir brauchen nicht nur Zement, sondern auch Sand.", "Potrzebujemy nie tylko cementu, ale i piasku.")], "Co robi sondern auch?", ["Dodaje drugą rzecz", "Kasuje pierwsze", "Pyta o godzinę"], 0, ["nicht", "nur", "heute"], "kein", "Wir brauchen nicht nur Zement, ___ auch Sand.", ["sondern", "aber", "weil"], 0, "Robię nie tylko spoiny, ale i odbiór.", "Ich mache nicht nur die Fugen, sondern auch die Abnahme.", ["nicht", "sondern"]),
        GrammarBook.g("zaim-a2", "Zaimek osobowy i dzierżawczy", "A2", "Ihn, sie, es", "Jak rzecz już padła, nie powtarzasz jej. Der Helm to ihn, die Leiter to sie, das Kabel to es.", "Der Helm? Ich hole ihn. Die Leiter? Ich sehe sie.", [GrammarBook.gl("Das Kabel sehe ich. Ich melde es.", "Widzę kabel. Zgłaszam go."), GrammarBook.gl("Den Chef rufe ich an.", "Dzwonię do szefa.")], [GrammarBook.gl("Die Palette ist schwer. Wir tragen sie zu zweit.", "Paleta jest ciężka. Niesiemy ją we dwóch.")], "Jak zastąpisz die Leiter?", ["sie", "ihn", "es"], 0, ["Ich", "hole", "ihn"], "sie", "Wir tragen ___ zu zweit.", ["sie", "ihn", "ihm"], 0, "Przyniosę go.", "Ich hole ihn.", ["hole", "ihn"]),
        GrammarBook.g("zaim-b1", "Zaimek osobowy i dzierżawczy", "B1", "Mir, dir, ihm", "Celownik osoby: mir, dir, ihm, ihr, uns. Dajesz komuś, mówisz komuś.", "Ich sage es dir. Kannst du mir helfen?", [GrammarBook.gl("Er gibt ihm den Beleg.", "Daje mu potwierdzenie."), GrammarBook.gl("Sie zeigt uns den Fehler.", "Pokazuje nam błąd.")], [GrammarBook.gl("Schick mir die Uhrzeit.", "Wyślij mi godzinę.")], "Jak powiesz mnie, kiedy ktoś ci daje?", ["mir", "mich", "mein"], 0, ["Kannst", "du", "mir", "helfen"], "mich", "Schick ___ die Uhrzeit.", ["mir", "mich", "mein"], 0, "Możesz mi pomóc?", "Kannst du mir helfen?", ["mir", "helfen"]),
        GrammarBook.g("zaim-b2", "Zaimek osobowy i dzierżawczy", "B2", "Dzierżawczy w bierniku", "Mein Helm przy podmiocie. Meinen Helm, kiedy bierzesz go jako cel. Meine Leiter zostaje meine.", "Ich nehme meinen Helm und meine Leiter.", [GrammarBook.gl("Kennst du seinen Kollegen?", "Znasz jego kolegę?"), GrammarBook.gl("Wo ist eure Pause?", "Gdzie jest wasza przerwa?")], [GrammarBook.gl("Ich lege meinen Ausweis auf den Tisch.", "Kładę dowód na stół.")], "Co przed der Helm, kiedy go bierzesz?", ["meinen", "mein", "meinem"], 0, ["Ich", "nehme", "meinen", "Helm"], "meine", "Wo ist ___ Pause?", ["eure", "euer", "euren"], 0, "Biorę swój kask.", "Ich nehme meinen Helm.", ["meinen"]),
        GrammarBook.g("weil-a1", "Zdania podrzędne z weil, dass, wenn, obwohl", "A1", "Bo, ale czasownik na końcu", "Weil znaczy bo. Jedna rzecz do zapamiętania: czasownik na końcu, nie zaraz po weil.", "Ich bleibe, weil ich krank bin.", [GrammarBook.gl("weil der Bus zu spät ist", "bo autobus jest spóźniony"), GrammarBook.gl("weil ich keine Zeit habe", "bo nie mam czasu")], [GrammarBook.gl("Ich komme nicht, weil ich arbeiten muss.", "Nie przyjdę, bo muszę pracować.")], "Gdzie jest bin?", ["Na końcu", "Zaraz po weil", "Przed ich"], 0, ["weil", "ich", "krank", "bin"], "bin ich", "Ich komme nicht, weil ich arbeiten ___.", ["muss", "muss ich", "ich muss"], 0, "Zostaję, bo jestem chory.", "Ich bleibe, weil ich krank bin.", ["weil", "bin"]),
        GrammarBook.g("spoj-a2", "Spójniki und, aber, oder, denn, sondern", "A2", "Oder i denn", "Oder daje wybór i nie rusza szyku. Denn znaczy bo, ale w przeciwieństwie do weil czasownik zostaje drugi.", "Ich bleibe hier, denn ich habe noch zu tun.", [GrammarBook.gl("Kaffee oder Tee?", "Kawa czy herbata?"), GrammarBook.gl("Ich gehe, denn der Bus kommt.", "Idę, bo autobus jedzie.")], [GrammarBook.gl("Wir nehmen die Leiter oder den Aufzug.", "Bierzemy drabinę albo windę.")], "Co robi denn z czasownikiem?", ["Zostawia go na drugim miejscu", "Wysyła go na koniec", "Kasuje go"], 0, ["Ich", "gehe", "denn", "der", "Bus", "kommt"], "weil", "Kaffee ___ Tee?", ["oder", "weil", "dass"], 0, "Idę, bo autobus jedzie.", "Ich gehe, denn der Bus kommt.", ["denn"]),
        GrammarBook.g("spoj-b1", "Spójniki und, aber, oder, denn, sondern", "B1", "Sondern po przeczeniu", "Sondern prostuje: nie to, tylko tamto. Aber tylko kontrastuje, nie wymienia błędu na poprawkę.", "Nicht die linke Wand, sondern die rechte.", [GrammarBook.gl("Ich nehme nicht den Bus, sondern die Bahn.", "Nie biorę autobusu, tylko kolejkę."), GrammarBook.gl("Das ist teuer, aber okay.", "To drogie, ale w porządku.")], [GrammarBook.gl("Nicht M8, sondern M10.", "Nie ósemki, tylko dziesiątki.")], "Kiedy sondern?", ["Jak prostujesz złą rzecz", "Jak dodajesz miłą uwagę", "Jak pytasz o godzinę"], 0, ["Nicht", "die", "linke", "Wand", "sondern", "die", "rechte"], "aber", "Nicht M8, ___ M10.", ["sondern", "aber", "oder"], 0, "Nie lewa ściana, tylko prawa.", "Nicht die linke Wand, sondern die rechte.", ["sondern"]),
        GrammarBook.g("spoj-b2", "Spójniki und, aber, oder, denn, sondern", "B2", "Zestaw w jednym mailu", "W krótkim mailu mieszasz spójniki świadomie: und łączy, aber kontrastuje, denn daje powód bez końca zdania.", "Ich komme um neun, aber ich fange hinten an, denn vorne fehlt Material.", [GrammarBook.gl("Der Termin steht, und die Akte ist da.", "Termin jest, i akta są."), GrammarBook.gl("Ich sage zu, denn der Freitag ist frei.", "Zgadzam się, bo piątek jest wolny.")], [GrammarBook.gl("Wir bleiben, aber nur bis vier.", "Zostajemy, ale tylko do czwartej.")], "Który spójnik daje powód i zostawia szyk?", ["denn", "weil", "dass"], 0, ["Ich", "sage", "zu", "denn", "der", "Freitag", "ist", "frei"], "weil", "Wir bleiben, ___ nur bis vier.", ["aber", "denn", "weil"], 0, "Zostajemy, ale tylko do czwartej.", "Wir bleiben, aber nur bis vier.", ["aber"]),
        GrammarBook.g("stop-a1", "Stopniowanie przymiotników", "A1", "Za bardzo: zu", "Zanim stopniujesz, łapiesz zu plus przymiotnik: zu schwer, zu spät, zu laut.", "Die Palette ist zu schwer.", [GrammarBook.gl("Du sprichst zu schnell.", "Mówisz za szybko."), GrammarBook.gl("Es ist zu spät.", "Jest za późno.")], [GrammarBook.gl("Der Schnitt ist zu tief.", "Nacięcie jest za głębokie.")], "Co znaczy zu schwer?", ["za ciężki", "cięższy", "najcięższy"], 0, ["Die", "Palette", "ist", "zu", "schwer"], "mehr", "Du sprichst zu ___.", ["schnell", "schneller", "am schnellsten"], 0, "Paleta jest za ciężka.", "Die Palette ist zu schwer.", ["zu", "schwer"]),
        GrammarBook.g("stop-b1", "Stopniowanie przymiotników", "B1", "Nieregularne stopnie", "Gut, besser, am besten. Gern, lieber, am liebsten. Viel, mehr, am meisten. Tych nie składasz z -er.", "Heute ist es besser. Ich arbeite lieber drinnen.", [GrammarBook.gl("Das ist am besten.", "To jest najlepsze."), GrammarBook.gl("Ich habe mehr Zeit als gestern.", "Mam więcej czasu niż wczoraj.")], [GrammarBook.gl("Lieber die kurze Leiter.", "Wolę krótką drabinę.")], "Jak powiesz lepiej?", ["besser", "guter", "mehr gut"], 0, ["Heute", "ist", "es", "besser"], "gut", "Ich arbeite ___ drinnen.", ["lieber", "gerner", "mehr gern"], 0, "Dziś jest lepiej.", "Heute ist es besser.", ["besser"]),
        GrammarBook.g("stop-b2", "Stopniowanie przymiotników", "B2", "Porównanie z als i so wie", "Als przy różnicy: länger als. So wie przy równości: so lang wie. Nie mieszasz ich.", "Die linke Seite ist länger als die rechte.", [GrammarBook.gl("Er spricht so schnell wie der Chef.", "Mówi tak szybko jak szef."), GrammarBook.gl("Das ist teurer als gestern.", "To droższe niż wczoraj.")], [GrammarBook.gl("Die Fuge ist breiter als acht Millimeter.", "Spoina jest szersza niż osiem milimetrów.")], "Które porównuje różnicę?", ["länger als", "so lang wie", "sehr lang"], 0, ["länger", "als", "die", "rechte"], "wie", "Er spricht so schnell ___ der Chef.", ["wie", "als", "dass"], 0, "Lewa strona jest dłuższa niż prawa.", "Die linke Seite ist länger als die rechte.", ["länger", "als"]),
        GrammarBook.g("przym-a1", "Przymiotniki i końcówki", "A1", "Najpierw luzem, bez końcówki", "Po ist przymiotnik nie dostaje końcówki: die Wand ist nass. Końcówka wchodzi dopiero przed rzeczownikiem.", "Die Wand ist nass. Der Helm ist neu.", [GrammarBook.gl("Das Teil ist schwer.", "Element jest ciężki."), GrammarBook.gl("Ich bin müde.", "Jestem zmęczony.")], [GrammarBook.gl("Der Boden ist nass.", "Podłoga jest mokra.")], "Gdzie nie ma końcówki?", ["po ist", "między der a rzeczownikiem", "zawsze"], 0, ["Die", "Wand", "ist", "nass"], "nasse", "Der Boden ist ___.", ["nass", "nasse", "nassen"], 0, "Ściana jest mokra.", "Die Wand ist nass.", ["ist", "nass"]),
        GrammarBook.g("przym-a2", "Przymiotniki i końcówki", "A2", "Po der, die, das jest -e", "Jak rodzajnik już pokazuje rodzaj, przymiotnik w mianowniku często dostaje samo -e.", "der neue Helm, die lange Leiter, das schwere Teil", [GrammarBook.gl("der freie Spind", "wolna szafka"), GrammarBook.gl("die laute Säge", "głośna piła")], [GrammarBook.gl("das nasse Kabel", "mokry kabel")], "Co pasuje?", ["der neue Helm", "der neuer Helm", "der neuen Helm"], 0, ["die", "lange", "Leiter"], "lang", "das ___ Teil", ["schwere", "schwer", "schwerer"], 0, "Nowa drabina jest długa.", "Die neue Leiter ist lang.", ["die", "neue"]),
        GrammarBook.g("przym-b2", "Przymiotniki i końcówki", "B2", "Po ein i kein końcówka niesie rodzaj", "Ein nie mówi, czy der czy das. Dlatego ein neuer Helm, ein neues Teil. W bierniku męskim: einen neuen Helm.", "ein neuer Helm, ein neues Teil, einen neuen Helm", [GrammarBook.gl("kein freier Spind", "żadna wolna szafka"), GrammarBook.gl("Ich brauche einen neuen Bohrer.", "Potrzebuję nowego wiertła.")], [GrammarBook.gl("Das ist kein schweres Teil.", "To nie jest ciężki element.")], "Co bierzesz, der Bohrer?", ["einen neuen Bohrer", "ein neuer Bohrer", "einen neue Bohrer"], 0, ["Ich", "brauche", "einen", "neuen", "Bohrer"], "neues", "Das ist kein ___ Teil.", ["schweres", "schwerer", "schwere"], 0, "Potrzebuję nowego wiertła.", "Ich brauche einen neuen Bohrer.", ["einen", "neuen"]),
        GrammarBook.g("imp-a2", "Tryb rozkazujący Imperativ", "A2", "Proszę do obcego", "Do kolegi hol. Do kierowcy, lekarza i urzędu: holen Sie, kommen Sie, warten Sie.", "Warten Sie bitte einen Moment.", [GrammarBook.gl("Zeigen Sie mir das bitte.", "Proszę mi to pokazać."), GrammarBook.gl("Sprechen Sie langsamer.", "Proszę mówić wolniej.")], [GrammarBook.gl("Legen Sie den Ausweis hierhin.", "Proszę położyć dowód tutaj.")], "Jak poprosisz urzędnika?", ["Zeigen Sie mir das.", "Zeig mir das.", "Du zeigst das."], 0, ["Warten", "Sie", "bitte"], "warte", "Sprechen ___ langsamer.", ["Sie", "du", "ihr"], 0, "Proszę chwilę poczekać.", "Warten Sie bitte einen Moment.", ["warten", "sie"]),
        GrammarBook.g("imp-b1", "Tryb rozkazujący Imperativ", "B1", "Nie rób tego", "Zakaz do kolegi: nie przed czasownikiem. Fass das nicht an. Geh da nicht rein.", "Fass das nicht an.", [GrammarBook.gl("Geh da nicht rein.", "Nie wchodź tam."), GrammarBook.gl("Lass die Säge nicht an.", "Nie zostawiaj piły włączonej.")], [GrammarBook.gl("Stell dich nicht unter die Last.", "Nie stawaj pod ładunkiem.")], "Gdzie jest nicht?", ["Po czasowniku, przed resztą", "Na końcu zawsze", "Przed fass"], 0, ["Fass", "das", "nicht", "an"], "kein", "Geh da nicht ___.", ["rein", "hinein gehen", "zu rein"], 0, "Nie dotykaj tego.", "Fass das nicht an.", ["fass", "nicht"]),
        GrammarBook.g("imp-b2", "Tryb rozkazujący Imperativ", "B2", "Rozkaz z zaimkiem", "Gib mir, zeig ihm, schick uns. Osoba w celowniku wchodzi zaraz po czasowniku.", "Schick mir die Uhrzeit.", [GrammarBook.gl("Gib ihm den Beleg.", "Daj mu potwierdzenie."), GrammarBook.gl("Zeig uns die Stelle.", "Pokaż nam to miejsce.")], [GrammarBook.gl("Lass mir den Helm da.", "Zostaw mi tu kask.")], "Co stoi zaraz po schick?", ["mir", "die Uhrzeit", "bitte zawsze"], 0, ["Schick", "mir", "die", "Uhrzeit"], "mich", "Gib ___ den Beleg.", ["ihm", "ihn", "er"], 0, "Wyślij mi godzinę.", "Schick mir die Uhrzeit.", ["schick", "mir"]),
        GrammarBook.g("zu-a1", "Konstrukcje z zu", "A1", "Czas na czynność", "Najprostszy zu to pora: Zeit zu gehen, Lust zu bleiben. Zu plus bezokolicznik, bez odmiany.", "Es ist Zeit zu gehen.", [GrammarBook.gl("Ich habe keine Lust zu bleiben.", "Nie mam ochoty zostawać."), GrammarBook.gl("Zeit, den Helm aufzusetzen.", "Czas założyć kask.")], [GrammarBook.gl("Es ist Zeit, Feierabend zu machen.", "Czas kończyć pracę.")], "Co stoi po Zeit?", ["zu gehen", "gehe", "gegangen"], 0, ["Es", "ist", "Zeit", "zu", "gehen"], "muss", "Ich habe keine Lust zu ___.", ["bleiben", "bleibe", "geblieben"], 0, "Czas iść.", "Es ist Zeit zu gehen.", ["zeit", "zu"]),
        GrammarBook.g("zu-a2", "Konstrukcje z zu", "A2", "Bez zu po modalnym", "Po müssen, können, wollen nie ma zu. Po vergessen i versuchen jest.", "Ich muss gehen. Ich vergesse zu sagen.", [GrammarBook.gl("Ich kann helfen.", "Mogę pomóc."), GrammarBook.gl("Vergiss nicht zu schließen.", "Nie zapomnij zamknąć.")], [GrammarBook.gl("Du sollst den Chef anrufen.", "Masz zadzwonić do szefa.")], "Gdzie zu jest błędem?", ["Ich muss zu gehen.", "Ich vergesse zu sagen.", "Es ist Zeit zu gehen."], 0, ["Ich", "kann", "helfen"], "zu", "Vergiss nicht zu ___.", ["schließen", "schließt", "geschlossen"], 0, "Muszę iść.", "Ich muss gehen.", ["muss", "gehen"]),
        GrammarBook.g("zu-b2", "Konstrukcje z zu", "B2", "Um ... zu, zamiast drugiego zdania", "Um ... zu mówi po co. Podmiot jest ten sam. Inaczej bierzesz damit i pełne zdanie.", "Ich bleibe, um den Bus zu kriegen.", [GrammarBook.gl("Er ruft an, um Bescheid zu sagen.", "Dzwoni, żeby dać znać."), GrammarBook.gl("Ich schicke die Mail, damit du den Termin hast.", "Wysyłam maila, żebyś miał termin.")], [GrammarBook.gl("Wir sichern die Plane, um den Regen abzuhalten.", "Mocujemy plandekę, żeby zatrzymać deszcz.")], "Kiedy um zu?", ["Jak osoba jest ta sama", "Jak w drugim zdaniu jest inna osoba", "Zamiast weil"], 0, ["um", "den", "Bus", "zu", "kriegen"], "damit", "Er ruft an, um Bescheid zu ___.", ["sagen", "sagt", "gesagt"], 0, "Zostaję, żeby złapać autobus.", "Ich bleibe, um den Bus zu kriegen.", ["um", "zu"]),
        GrammarBook.g("fut-a1", "Futur", "A1", "Jutro bez werden", "Na A1 jutro mówisz czasem teraźniejszym i słowem morgen, heute Abend, nächste Woche.", "Heute Abend rufe ich an.", [GrammarBook.gl("Morgen habe ich frei.", "Jutro mam wolne."), GrammarBook.gl("Um sechs komme ich.", "O szóstej przyjdę.")], [GrammarBook.gl("Nächste Woche beginnt die Schicht früher.", "W przyszłym tygodniu zmiana zaczyna się wcześniej.")], "Czego nie potrzebujesz?", ["Osobnego czasu przyszłego", "Słowa morgen", "Czasownika"], 0, ["Heute", "Abend", "rufe", "ich", "an"], "werde", "Morgen ___ ich frei.", ["habe", "werden", "hatte"], 0, "Dziś wieczorem zadzwonię.", "Heute Abend rufe ich an.", ["heute", "rufe"]),
        GrammarBook.g("fut-b1", "Futur", "B1", "Versprechen z werden", "Werden plus bezokolicznik na końcu, kiedy coś obiecujesz albo ktoś ci grozi terminem.", "Ich werde das heute noch schicken.", [GrammarBook.gl("Das wird knapp.", "Będzie ciasno."), GrammarBook.gl("Wir werden die Wand morgen prüfen.", "Sprawdzimy ścianę jutro.")], [GrammarBook.gl("Ich werde den Beleg nicht verlieren.", "Nie zgubię potwierdzenia.")], "Gdzie jest schicken?", ["Na końcu", "Zaraz po werde", "Na początku"], 0, ["Ich", "werde", "das", "heute", "noch", "schicken"], "werde", "Das ___ knapp.", ["wird", "werden", "wurde"], 0, "Wyślę to jeszcze dziś.", "Ich werde das heute noch schicken.", ["werde", "schicken"]),
        GrammarBook.g("fut-b2", "Futur", "B2", "Przypuszczenie", "Wird plus wohl to nie obietnica, tylko zgadywanie: pewnie tak będzie.", "Der Bus wird wohl wieder zu spät kommen.", [GrammarBook.gl("Das wird schon passen.", "To pewnie będzie w porządku."), GrammarBook.gl("Er wird noch auf der Baustelle sein.", "Pewnie jeszcze jest na budowie.")], [GrammarBook.gl("Die Lieferung wird wohl erst morgen kommen.", "Dostawa pewnie przyjdzie dopiero jutro.")], "Co dodaje wohl?", ["Że zgadujesz", "Że rozkazujesz", "Że to już się stało"], 0, ["Das", "wird", "schon", "passen"], "wohl", "Er wird noch auf der Baustelle ___.", ["sein", "ist", "war"], 0, "Autobus pewnie znowu się spóźni.", "Der Bus wird wohl wieder zu spät kommen.", ["wird", "wohl"]),
        GrammarBook.g("pas-a1", "Strona bierna Passiv", "A1", "Tabliczka, nie teoria", "Na drzwiach i na placu czytasz wird plus ge-: tu się czegoś nie robi. Nie musisz sam budować strony biernej.", "Hier wird nicht geraucht.", [GrammarBook.gl("Betreten der Baustelle verboten.", "Wstęp na budowę wzbroniony."), GrammarBook.gl("Helme werden kontrolliert.", "Kaski są sprawdzane.")], [GrammarBook.gl("Hier wird nicht geparkt.", "Tu się nie parkuje.")], "Co znaczy hier wird nicht geraucht?", ["Tu się nie pali", "Ja paliłem wczoraj", "Palenie jest obowiązkowe"], 0, ["Hier", "wird", "nicht", "geraucht"], "rauche", "Hier wird nicht ___.", ["geparkt", "parken", "parkte"], 0, "Tu się nie pali.", "Hier wird nicht geraucht.", ["wird", "geraucht"]),
        GrammarBook.g("pas-a2", "Strona bierna Passiv", "A2", "Zostanie zrobione", "Jak liczy się robota, a nie kto: wird plus forma z ge- na końcu.", "Das wird morgen gemacht.", [GrammarBook.gl("Die Palette wird heute geliefert.", "Paleta zostanie dziś dostarczona."), GrammarBook.gl("Der Fehler wird notiert.", "Błąd zostanie zapisany.")], [GrammarBook.gl("Die Wand wird neu verfugt.", "Ściana będzie na nowo spoinowana.")], "Kto jest ważny w tym zdaniu?", ["Czynność, nie osoba", "Tylko ja", "Tylko szef z imienia"], 0, ["Das", "wird", "morgen", "gemacht"], "habe", "Die Palette wird heute ___.", ["geliefert", "liefern", "lieferte"], 0, "To zrobią jutro.", "Das wird morgen gemacht.", ["wird", "gemacht"]),
        GrammarBook.g("pas-b2", "Strona bierna Passiv", "B2", "Zostało zrobione", "O wczoraj: wurde plus ge- na końcu. W mowie i tak często wracasz do man hat das gemacht.", "Die Wand wurde gestern abgenommen.", [GrammarBook.gl("Der Termin wurde verschoben.", "Termin został przesunięty."), GrammarBook.gl("Man hat den Termin verschoben.", "Przesunięto termin.")], [GrammarBook.gl("Die Lieferung wurde abgelehnt.", "Dostawa została odrzucona.")], "Które jest stroną bierną o wczoraj?", ["wurde verschoben", "hat verschoben", "wird verschieben"], 0, ["Die", "Wand", "wurde", "gestern", "abgenommen"], "wird", "Der Termin wurde ___.", ["verschoben", "verschieben", "schiebt"], 0, "Ścianę odebrano wczoraj.", "Die Wand wurde gestern abgenommen.", ["wurde", "abgenommen"]),
        GrammarBook.g("pot-a1", "Typowe niemieckie konstrukcje potoczne", "A1", "Krótkie tak i nie", "Na placu nie budujesz referatu. Passt, genau, moment, alles klar zamykają sprawę.", "Passt. Alles klar. Moment.", [GrammarBook.gl("Genau.", "Dokładnie."), GrammarBook.gl("Geht klar.", "Da się zrobić.")], [GrammarBook.gl("Bin gleich da.", "Zaraz jestem.")], "Co znaczy passt?", ["Może być, zgoda", "Nie pasuje rozmiar i koniec rozmowy", "Jest za późno"], 0, ["Alles", "klar"], "genau", "___.", ["Passt", "Passen", "Gepasst"], 0, "Zaraz jestem.", "Bin gleich da.", ["gleich"]),
        GrammarBook.g("pot-b2", "Typowe niemieckie konstrukcje potoczne", "B2", "Doch i mal", "Doch po przeczeniu znaczy wręcz tak. Mal zmiękcza prośbę: schau mal, komm mal. Bez mal brzmisz ostrzej.", "Doch, das geht. Schau mal kurz.", [GrammarBook.gl("Kannst du mal halten?", "Możesz na chwilę potrzymać?"), GrammarBook.gl("Doch, ich war da.", "A właśnie, że byłem.")], [GrammarBook.gl("Komm mal her, bevor du hochgehst.", "Podejdź na chwilę, zanim wejdziesz.")], "Co znaczy doch po nein?", ["Wręcz przeciwnie, tak", "Nigdy", "Być może jutro"], 0, ["Kannst", "du", "mal", "halten"], "bitte", "___, ich war da.", ["Doch", "Nein", "Kein"], 0, "Możesz na chwilę potrzymać?", "Kannst du mal halten?", ["mal"])
    ]
